window.RP_SESSION={"id":"S-ce59abb48538","messages":[{"id":"RP-II-0104154","time":"2026-06-01T23:06:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"덥네요. 덥습니다. 이제 6월이니 그럴만 하죠.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104155","time":"2026-06-01T23:06:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104156","time":"2026-06-01T23:06:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"근데 좀 과하게 덥지 않나요?","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104157","time":"2026-06-01T23:06:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"하고 보니, 카펫은 여름용으로 잘 바뀌어있는데 커튼들이 아직 겨울용이었군요!","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104158","time":"2026-06-01T23:08:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 어쩐지 요새 요리하면 땀이 차더라니!","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104159","time":"2026-06-01T23:08:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"아니, 이건 역시 날씨 때문이 맞을지도요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104160","time":"2026-06-01T23:08:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"사실 처음 올 때도 힘들어서 땀이 찼고...","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104161","time":"2026-06-01T23:08:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...역시 잘 모르겠네요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104162","time":"2026-06-01T23:08:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"여름 커튼이나 걸러가야겠습니다.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104163","time":"2026-06-01T23:09:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"저벅, 탁. 저벅 탁.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104164","time":"2026-06-01T23:10:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"시간이 여유가 있으니, 천천히 걸어도 되겠지요. 사이먼은 창고에 도착했습니다. 근데 여기 온 지가 오래 됐다보니, 아직 물건들이 기억하는 자리에 있을지 잘 모르겠네요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104165","time":"2026-06-01T23:10:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104166","time":"2026-06-01T23:10:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'사이먼 피터 포레스트'의 지능 판정 :\n[8] + [0] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0104167","time":"2026-06-01T23:12:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아, 여깄습니다. 예전과 같네요. 낮선 동료들 주위 익숙한 풍경과 같이 그대로인 건 언제나 있어요. 그 중 사이먼은 언제까지 그대로일 수 있을까요. 애초에 지금 그대로이긴 할 까요?","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104168","time":"2026-06-01T23:13:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"뭐, 중요한 일은 아니지요. 사람은 언제나 좋은 쪽으로든 아니든 성장하게 됩니다. 사이먼도 예외는 아니겠고요. 지금 중요한 건 커튼을 교체하는 겁니다.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104169","time":"2026-06-01T23:15:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"흣챠.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104170","time":"2026-06-01T23:15:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104171","time":"2026-06-01T23:15:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'사이먼 피터 포레스트'의 힘 판정 :\n[9] + [0] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0104172","time":"2026-06-01T23:16:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"좋아요. 얇은 천이라 그런지 많이씩 옮겨집니다. 이대로 한두번 더 왔다갔다하면 다 되겠지요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104173","time":"2026-06-01T23:19:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 우선 1층에 커튼부터 교체해야 이치에 맞겠죠? 우선 두꺼운 옛 커튼들을 떼어내고 올 겨울을 위해 잘 개켜둡니다. 나 없는 새 바꿨는지 색이 더 진한 느낌이네요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104174","time":"2026-06-01T23:19:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"봉은...","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104175","time":"2026-06-01T23:19:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"흠.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104176","time":"2026-06-01T23:19:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104177","time":"2026-06-01T23:19:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 7 = 7\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0104178","time":"2026-06-01T23:20:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"쩝. 많이 낡았네요. 얜 교체 안 했나봅니다. 그래도 큰 충격만 안 주면 올해까진 쓸 수 있겠어요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104179","time":"2026-06-01T23:21:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"unresolved","type":"dialogue","body":"큰 충격의 예시 - 조바와 엘타","characters":[]},{"id":"RP-II-0104180","time":"2026-06-01T23:21:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"잠깐, 여기 있어야 할 가구 하나가 안 보이는데요. 어디 갔을까요?","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104181","time":"2026-06-01T23:22:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"흠...","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104182","time":"2026-06-01T23:22:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"하나 뿐 만이 아닌거 같아요. 쓸쓸하지만 어쩔 수 없죠.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104183","time":"2026-06-01T23:23:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"이제 가장 피곤한 부분입니다. 핀 부분에 커튼을 다는 것이요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104184","time":"2026-06-01T23:24:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"어릴 적부터 셈이 약해서 매번 순서를 헷갈려 몇 번이고 고쳐 달곤 했습니다.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104185","time":"2026-06-01T23:24:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104186","time":"2026-06-01T23:24:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104187","time":"2026-06-01T23:24:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104188","time":"2026-06-01T23:25:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"1층 끝!","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104189","time":"2026-06-01T23:25:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"상당히 뿌듯하군요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104190","time":"2026-06-01T23:29:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"나머지는","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104191","time":"2026-06-01T23:29:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"사이먼이 어찌해줄 수 있는 게 아니군요! 벽에 단열재 아직 있는지나 확인해서 나중에 누구 불러야겠습니다.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104192","time":"2026-06-02T00:01:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"음","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104193","time":"2026-06-02T00:02:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"없네요.","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104194","time":"2026-06-02T00:49:00+09:00","room":"RP II","name":"사이먼 포레스트","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3ea4affc20fd"]},{"id":"RP-II-0104195","time":"2026-06-02T00:49:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]},{"id":"RP-II-0104196","time":"2026-06-02T01:02:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"unresolved","type":"dialogue","body":"https://youtu.be/srOanWPkCDE?si=yMG1MbsNhkRCDkB_","characters":[]}]};
